/* Cohesive 4-Color Palette: Navy, Emerald/Sage, Light Parchment, Pixel Red */
:root {
  --bg-color: #1a1c23;
  --card-bg: #272c3d;
  --text-main: #f0f4f8;
  --text-dim: #94a3b8;
  --primary: #38bdf8;
  --accent: #4ade80;
  --danger: #f43f5e;
  --border-outer: #0f1117;
  --border-highlight: #475569;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  font-family: "Courier New", Courier, monospace, system-ui;
  background-color: var(--bg-color);
  color: var(--text-main);
  font-size: 16px;
  line-height: 1.5;
  min-height: 100vh;
  padding: 24px 16px;
  display: flex;
  justify-content: center;
  align-items: flex-start;
}

.app-container {
  width: 100%;
  max-width: 560px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.pixel-header {
  text-align: center;
  padding: 12px;
  border: 4px solid var(--border-outer);
  background: var(--card-bg);
  box-shadow: 4px 4px 0 var(--border-outer);
}

.title {
  font-size: 1.75rem;
  letter-spacing: -1px;
  text-transform: uppercase;
  color: var(--primary);
}

.subtitle {
  color: var(--text-dim);
  font-size: 1rem;
  margin-top: 4px;
}

/* Pixel Card Styling with Chunky Borders */
.pixel-card {
  background: var(--card-bg);
  border: 4px solid var(--border-outer);
  box-shadow: 4px 4px 0 var(--border-outer);
  padding: 18px;
}

.card-title {
  font-size: 1.2rem;
  margin-bottom: 14px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border-bottom: 3px solid var(--border-highlight);
  padding-bottom: 6px;
}

/* Form Layout */
.grid-form {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}

.full-width {
  grid-column: 1 / -1;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

label {
  font-size: 0.9rem;
  font-weight: bold;
  color: var(--text-dim);
  text-transform: uppercase;
}

input {
  font-family: inherit;
  font-size: 1rem;
  padding: 10px 12px;
  background: #11141e;
  color: var(--text-main);
  border: 3px solid var(--border-highlight);
  outline: none;
}

input:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 2px var(--primary);
}

/* Pixel Buttons */
.pixel-btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  text-transform: uppercase;
  padding: 12px 16px;
  cursor: pointer;
  border: 3px solid var(--border-outer);
  box-shadow: 3px 3px 0 var(--border-outer);
  transition: transform 0.05s ease, box-shadow 0.05s ease;
}

.pixel-btn:hover {
  filter: brightness(1.1);
}

.pixel-btn:focus-visible {
  outline: 2px dashed #fff;
  outline-offset: 2px;
}

.pixel-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0 var(--border-outer);
}

.btn-primary {
  background: var(--primary);
  color: #0b1120;
  width: 100%;
}

.btn-secondary {
  background: #475569;
  color: var(--text-main);
  font-size: 0.8rem;
  padding: 6px 10px;
}

.btn-delete {
  background: var(--danger);
  color: #fff;
  font-size: 0.85rem;
  padding: 6px 10px;
}

/* Dashboard Stats */
.dashboard {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  text-align: center;
}

.stat-box {
  background: #11141e;
  padding: 10px 6px;
  border: 2px solid var(--border-highlight);
}

.stat-label {
  display: block;
  font-size: 0.8rem;
  color: var(--text-dim);
  text-transform: uppercase;
  margin-bottom: 4px;
}

.stat-value {
  font-size: 1.15rem;
  font-weight: bold;
  color: var(--accent);
}

/* Over-Budget Red State */
.over-budget {
  color: var(--danger) !important;
}

.stat-box.over-budget-box {
  border-color: var(--danger) !important;
}

.alert-banner {
  background: var(--danger);
  color: #fff;
  font-weight: bold;
  text-align: center;
  padding: 10px;
  border: 3px solid var(--border-outer);
  box-shadow: 3px 3px 0 var(--border-outer);
  letter-spacing: 0.5px;
}

/* Grocery Items List */
.cart-header-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
}

.cart-header-row .card-title {
  margin-bottom: 0;
  border-bottom: none;
  padding-bottom: 0;
}

.empty-state {
  color: var(--text-dim);
  font-style: italic;
  padding: 18px 0;
  text-align: center;
}

.grocery-items-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 12px;
}

.grocery-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: #11141e;
  padding: 10px 14px;
  border: 2px solid var(--border-highlight);
  gap: 10px;
}

.item-info {
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.item-name-text {
  font-weight: bold;
  word-break: break-word;
}

.item-calculation-text {
  font-size: 0.85rem;
  color: var(--text-dim);
}

.item-subtotal-text {
  font-weight: bold;
  margin-right: 8px;
  white-space: nowrap;
}

@media (max-width: 480px) {
  .dashboard {
    grid-template-columns: 1fr;
  }
  .grid-form {
    grid-template-columns: 1fr;
  }
}

document.addEventListener("DOMContentLoaded", function () {
  // State
  var state = {
    budget: 50.0,
    items: []
  };

  // DOM references
  var budgetInput = document.getElementById("budget-input");
  var budgetDisplay = document.getElementById("budget-display");
  var totalSpentDisplay = document.getElementById("total-spent");
  var remainingBudgetDisplay = document.getElementById("remaining-budget");
  var budgetAlert = document.getElementById("budget-alert");
  var itemForm = document.getElementById("item-form");
  var itemNameInput = document.getElementById("item-name");
  var itemPriceInput = document.getElementById("item-price");
  var itemQtyInput = document.getElementById("item-qty");
  var groceryList = document.getElementById("grocery-list");
  var emptyCartMsg = document.getElementById("empty-cart-msg");
  var itemCountDisplay = document.getElementById("item-count");
  var clearAllBtn = document.getElementById("clear-all-btn");

  function formatCurrency(num) {
    var isNeg = num < 0;
    var abs = Math.abs(num).toFixed(2);
    return (isNeg ? "-$ " : "$ ") + abs;
  }

  function render() {
    // Calculate totals
    var totalSpent = 0;
    for (var i = 0; i < state.items.length; i++) {
      totalSpent += state.items[i].price * state.items[i].quantity;
    }
    // Avoid floating point jitter
    totalSpent = Math.round(totalSpent * 100) / 100;
    var remaining = Math.round((state.budget - totalSpent) * 100) / 100;
    var isOverBudget = remaining < 0;

    // Update dashboard
    budgetDisplay.textContent = formatCurrency(state.budget);
    totalSpentDisplay.textContent = formatCurrency(totalSpent);
    remainingBudgetDisplay.textContent = formatCurrency(remaining);
    itemCountDisplay.textContent = state.items.length;

    // Handle over budget color markings
    if (isOverBudget) {
      totalSpentDisplay.classList.add("over-budget");
      remainingBudgetDisplay.classList.add("over-budget");
      budgetAlert.removeAttribute("hidden");
    } else {
      totalSpentDisplay.classList.remove("over-budget");
      remainingBudgetDisplay.classList.remove("over-budget");
      budgetAlert.setAttribute("hidden", "");
    }

    // Empty state & Clear All button
    if (state.items.length === 0) {
      emptyCartMsg.removeAttribute("hidden");
      clearAllBtn.setAttribute("hidden", "");
    } else {
      emptyCartMsg.setAttribute("hidden", "");
      clearAllBtn.removeAttribute("hidden");
    }

    // Render grocery list items
    groceryList.innerHTML = "";
    state.items.forEach(function (item) {
      var li = document.createElement("li");
      li.className = "grocery-item";

      var subtotal = Math.round(item.price * item.quantity * 100) / 100;

      var infoDiv = document.createElement("div");
      infoDiv.className = "item-info";

      var nameSpan = document.createElement("span");
      nameSpan.className = "item-name-text";
      nameSpan.textContent = item.name;

      var calcSpan = document.createElement("span");
      calcSpan.className = "item-calculation-text";
      calcSpan.textContent = formatCurrency(item.price) + " × " + item.quantity;

      infoDiv.appendChild(nameSpan);
      infoDiv.appendChild(calcSpan);

      var subtotalSpan = document.createElement("span");
      subtotalSpan.className = "item-subtotal-text";
      subtotalSpan.textContent = formatCurrency(subtotal);

      var delBtn = document.createElement("button");
      delBtn.type = "button";
      delBtn.className = "pixel-btn btn-delete";
      delBtn.textContent = "X";
      delBtn.setAttribute("aria-label", "Remove " + item.name + " from list");
      delBtn.addEventListener("click", function () {
        removeItem(item.id);
      });

      li.appendChild(infoDiv);
      li.appendChild(subtotalSpan);
      li.appendChild(delBtn);

      groceryList.appendChild(li);
    });
  }

  function removeItem(id) {
    state.items = state.items.filter(function (it) {
      return it.id !== id;
    });
    render();
  }

  // Event Listeners
  budgetInput.addEventListener("input", function () {
    var val = parseFloat(budgetInput.value);
    state.budget = isNaN(val) || val < 0 ? 0 : val;
    render();
  });

  itemForm.addEventListener("submit", function (e) {
    e.preventDefault();
    var name = itemNameInput.value.trim();
    var price = parseFloat(itemPriceInput.value);
    var qty = parseInt(itemQtyInput.value, 10);

    if (!name || isNaN(price) || price <= 0 || isNaN(qty) || qty <= 0) {
      return;
    }

    var newItem = {
      id: Date.now().toString() + Math.random().toString(36).slice(2, 6),
      name: name,
      price: price,
      quantity: qty
    };

    state.items.push(newItem);
    itemNameInput.value = "";
    itemPriceInput.value = "";
    itemQtyInput.value = "1";
    itemNameInput.focus();
    render();
  });

  clearAllBtn.addEventListener("click", function () {
    if (state.items.length > 0) {
      state.items = [];
      render();
    }
  });

  // Initial render
  render();
});
